def partitionLabels(s):
    """Split string into max segments where each char appears in exactly one segment."""
    last_index = {}
    for i, c in enumerate(s):
        last_index[c] = i

    result = []
    start = 0
    end = 0

    for i, c in enumerate(s):
        end = max(end, last_index[c])

        if i == end:
            result.append(i - start + 1)
            start = i + 1

    return result
